import { WGSL_SHADERS } from './shaders.wgsl';

export class WebGPUProcessor {
  private device: GPUDevice | null = null;
  private isInitialized = false;

  async init(): Promise<boolean> {
    if (this.isInitialized) return true;
    if (!navigator.gpu) {
      console.warn("WebGPU не поддерживается браузером.");
      return false;
    }

    try {
      const adapter = await navigator.gpu.requestAdapter();
      if (!adapter) throw new Error("Нет доступного GPU адаптера.");

      this.device = await adapter.requestDevice();
      this.isInitialized = true;
      console.log("WebGPU успешно инициализирован");
      return true;
    } catch (e) {
      console.error("Ошибка инициализации WebGPU:", e);
      return false;
    }
  }

  getDevice(): GPUDevice | null {
    return this.device;
  }

  async runPixelPipeline(imgBuffer: Uint8Array, width: number, height: number, palette: [number, number, number][], radius: number, detail: number, importanceMap: Float32Array | null = null): Promise<Uint8Array | null> {
    if (!this.device) return null;
    
    const device = this.device;
    const kColors = palette.length;

    const shaderModule = device.createShaderModule({
        code: WGSL_SHADERS
    });

    const paramsBuffer = device.createBuffer({
        size: 24, // 6 * 4 bytes = 24
        usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });

    const aiEnabled = importanceMap ? 1 : 0;
    const paramsData = new Uint32Array([
        width, height, radius, kColors, detail, aiEnabled
    ]);
    device.queue.writeBuffer(paramsBuffer, 0, paramsData);

    const paletteLabData = new Float32Array(kColors * 4);
    for (let i = 0; i < kColors; i++) {
        const lab = this.rgbToLab(palette[i]);
        paletteLabData[i * 4] = lab[0];
        paletteLabData[i * 4 + 1] = lab[1];
        paletteLabData[i * 4 + 2] = lab[2];
        paletteLabData[i * 4 + 3] = 1.0;
    }

    const paletteBuffer = device.createBuffer({
        size: kColors * 16,
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(paletteBuffer, 0, paletteLabData);

    const paletteRGBBuffer = device.createBuffer({
        size: Math.max(16, kColors * 16),
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(paletteRGBBuffer, 0, new Uint32Array(Math.max(4, kColors * 4)));

    const bindGroupLayout0 = device.createBindGroupLayout({
        entries: [
            { binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: "uniform" } },
            { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer: { type: "read-only-storage" } },
            { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer: { type: "read-only-storage" } }
        ]
    });

    const bindGroup0 = device.createBindGroup({
        layout: bindGroupLayout0,
        entries: [
            { binding: 0, resource: { buffer: paramsBuffer } },
            { binding: 1, resource: { buffer: paletteBuffer } },
            { binding: 2, resource: { buffer: paletteRGBBuffer } }
        ]
    });

    const imgGPUBuffer = device.createBuffer({
        size: width * height * 4,
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(imgGPUBuffer, 0, imgBuffer.buffer, imgBuffer.byteOffset, imgBuffer.byteLength);

    const outMaskBuffer = device.createBuffer({
        size: width * height * 4,
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST,
    });

    const finalMaskBuffer = device.createBuffer({
        size: width * height * 4,
        usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST,
    });

    let importanceGPUBuffer: GPUBuffer;
    if (importanceMap) {
        // Importance map is already Float32Array — direct upload
        importanceGPUBuffer = device.createBuffer({
            size: width * height * 4,
            usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
        });
        device.queue.writeBuffer(importanceGPUBuffer, 0, importanceMap.buffer, importanceMap.byteOffset, importanceMap.byteLength);
    } else {
        // Dummy buffer with neutral importance (0.5)
        const dummy = new Float32Array(1);
        dummy[0] = 0.5;
        importanceGPUBuffer = device.createBuffer({
            size: 4,
            usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
        });
        device.queue.writeBuffer(importanceGPUBuffer, 0, dummy.buffer);
    }

    const bindGroupLayout1 = device.createBindGroupLayout({
        entries: [
            { binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: "read-only-storage" } },
            { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
            { binding: 2, visibility: GPUShaderStage.COMPUTE, buffer: { type: "storage" } },
            { binding: 3, visibility: GPUShaderStage.COMPUTE, buffer: { type: "read-only-storage" } }
        ]
    });

    const bindGroup1 = device.createBindGroup({
        layout: bindGroupLayout1,
        entries: [
            { binding: 0, resource: { buffer: imgGPUBuffer } },
            { binding: 1, resource: { buffer: outMaskBuffer } },
            { binding: 2, resource: { buffer: finalMaskBuffer } },
            { binding: 3, resource: { buffer: importanceGPUBuffer } }
        ]
    });

    const pipelineLayout = device.createPipelineLayout({
        bindGroupLayouts: [bindGroupLayout0, bindGroupLayout1]
    });

    const filterPipeline = device.createComputePipeline({
        layout: pipelineLayout,
        compute: { module: shaderModule, entryPoint: 'filter_and_quantize' }
    });

    const commandEncoder = device.createCommandEncoder();
    const workgroupsX = Math.ceil(width / 16);
    const workgroupsY = Math.ceil(height / 16);

    // Pass 1: Bilateral + Assign
    const pass1 = commandEncoder.beginComputePass();
    pass1.setPipeline(filterPipeline);
    pass1.setBindGroup(0, bindGroup0);
    pass1.setBindGroup(1, bindGroup1);
    pass1.dispatchWorkgroups(workgroupsX, workgroupsY, 1);
    pass1.end();

    // Readback
    const stagingBuffer = device.createBuffer({
        size: width * height * 4,
        usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
    });
    
    commandEncoder.copyBufferToBuffer(outMaskBuffer, 0, stagingBuffer, 0, width * height * 4);
    device.queue.submit([commandEncoder.finish()]);

    await stagingBuffer.mapAsync(GPUMapMode.READ);
    const rawMask = new Uint32Array(stagingBuffer.getMappedRange());
    
    const maskU8 = new Uint8Array(width * height);
    for (let i = 0; i < maskU8.length; i++) {
        maskU8[i] = rawMask[i];
    }
    stagingBuffer.unmap();
    
    // Clean up
    imgGPUBuffer.destroy();
    outMaskBuffer.destroy();
    finalMaskBuffer.destroy();
    stagingBuffer.destroy();
    paramsBuffer.destroy();
    paletteBuffer.destroy();
    paletteRGBBuffer.destroy();
    if (importanceGPUBuffer) {
        importanceGPUBuffer.destroy();
    }

    return maskU8;
  }

  private rgbToLab(c: [number, number, number]): [number, number, number] {
    let r = c[0] / 255.0;
    let g = c[1] / 255.0;
    let b = c[2] / 255.0;

    r = r > 0.04045 ? Math.pow((r + 0.055) / 1.055, 2.4) : r / 12.92;
    g = g > 0.04045 ? Math.pow((g + 0.055) / 1.055, 2.4) : g / 12.92;
    b = b > 0.04045 ? Math.pow((b + 0.055) / 1.055, 2.4) : b / 12.92;

    let x = (r * 0.4124564 + g * 0.3575761 + b * 0.1804375) / 0.95047;
    let y = (r * 0.2126729 + g * 0.7151522 + b * 0.0721750) / 1.00000;
    let z = (r * 0.0193339 + g * 0.1191920 + b * 0.9503041) / 1.08883;

    x = x > 0.008856 ? Math.pow(x, 1 / 3) : (7.787 * x) + 16 / 116;
    y = y > 0.008856 ? Math.pow(y, 1 / 3) : (7.787 * y) + 16 / 116;
    z = z > 0.008856 ? Math.pow(z, 1 / 3) : (7.787 * z) + 16 / 116;

    return [(116 * y) - 16, 500 * (x - y), 200 * (y - z)];
  }
}

export const gpuProcessor = new WebGPUProcessor();