// src/generator/utils/image.worker.ts
import { rgbToLab, rgbToHsl, deltaE00 } from '../../utils/colorMath';
import { applyArtisticStrategy, multiLevelNotan, customPaletteStrategy, blendWithIntensity, canonicalizeStyledPalette } from '../../utils/colorStrategies';
import { generateSvgTemplate, generateArtisticHtmlTemplate, generatePbnHtmlTemplate } from './exportTemplates';

import { resolveAllLabelCollisions } from './worker/labels';
import { escapeXml, rleEncode } from './worker/encoding';

export interface SolverCandidate {
  drops: number[];
  delta: number;
  total: number;
  used: number;
}

function computeArtisticColor(
  rgbArr: [number, number, number],
  artisticStep: number,
  artisticPresetId: string,
  notanLevels: number,
  notanThreshold: number,
  artIntensity: number,
  customArtPalette?: [number, number, number][],
): [number, number, number] {
  if (artisticStep === 1) { // Светотень (Notan)
    return multiLevelNotan(rgbArr, notanLevels, notanThreshold);
  } else if (artisticStep === 2) { // Художественная стилизация
    if (artisticPresetId === 'original') return rgbArr;
    
    if (customArtPalette && customArtPalette.length >= 2) {
      const styled = customPaletteStrategy(rgbArr, customArtPalette);
      if (artIntensity < 100) {
        return blendWithIntensity(rgbArr, styled, artIntensity);
      }
      return styled;
    }
    return applyArtisticStrategy(rgbArr, artisticPresetId as any, artIntensity);
  } else {
    // Шаг 0 (Контуры) и 3 (Детали) - используем оригинальный цвет
    return rgbArr;
  }
}

import initWasm, { process_image, build_smooth_chains_wasm, extract_palette, process_from_mask, vectorize_mask } from '../../wasm/wasm_engine';
import { gpuProcessor } from './imageProcessing/webgpuCore';

let wasmInited = false;

// Сборка результата ядра (общая для генерации и ручного редактора). Возвращает
// объект data (совпадает с ProcessingResult) и список переносимых буферов.
function buildResultMessage(res: any, W: number, H: number, detail: number) {
  const flatEdges = new Float32Array(res.boundary_edges);
  const simplifyEps = detail <= 2 ? 0.5 : detail <= 4 ? 0.4 : detail <= 7 ? 0.3 : 0.1;
  const allChains = build_smooth_chains_wasm(flatEdges, simplifyEps, 4) as [number, number][][];
  // Отбрасываем цепочки, идущие вдоль края изображения — это внешняя «рамка»
  // (граница крайних зон совпадает с краем картинки). Раньше сравнивали строго
  // с 0/W/H, но после сглаживания контуров край смещается на ~1px, поэтому рамка
  // просачивалась в результат и печаталась всегда. Сравниваем с допуском.
  const T = 1.25;
  const chains = allChains.filter((ch) => {
    const isTop = ch.every(p => p[1] <= T);
    const isBottom = ch.every(p => p[1] >= H - T);
    const isLeft = ch.every(p => p[0] <= T);
    const isRight = ch.every(p => p[0] >= W - T);
    return !(isTop || isBottom || isLeft || isRight);
  });

  const labelMask = new Uint8Array(res.label_mask);
  const previewBuffer = new Uint8Array(res.preview_buffer).buffer;

  const pal: Record<number, [number, number, number]> = {};
  res.palette.forEach((val: any, key: any) => { pal[key] = val; });

  const contoursData = res.contours.map((c: any) => ({
    points: c.points,
    smoothPoints: c.points,
    labelId: c.label_id,
    center: c.center,
    maxDist: c.max_dist,
    area: c.area,
    labelPositions: c.label_positions.map((lp: any) => ({ x: lp.x, y: lp.y, maxDist: lp.max_dist })),
  }));

  resolveAllLabelCollisions(contoursData, W, H, labelMask);

  const data = {
    previewBuffer,
    imgW: W,
    imgH: H,
    contoursData,
    colorPalette: pal,
    validLabels: res.valid_labels,
    scaleFactor: 1,
    autoColors: res.palette.size,
    autoDetail: detail,
    labelMaskBuffer: labelMask.buffer,
    boundaryEdgesBuffer: flatEdges.buffer,
    chains,
  };
  return { data, transfer: [previewBuffer, labelMask.buffer, flatEdges.buffer] as Transferable[] };
}

// ─────────────────────────────────────────────────────────────
// КОЖЕЗАВИСИМАЯ ПАЛИТРА (fix «мёртвых лиц»)
// ─────────────────────────────────────────────────────────────
//
// Корневой дефект портретов: общая палитра не резервирует ряд телесных тонов,
// поэтому тонкие блики/полутени кожи сопоставляются с НЕ-телесными цветами
// (синий от неба/волос, розовый от одежды) → лицо «в пятнах» и не похоже.
// Решение: до сегментации находим реальные оттенки кожи ЭТОГО лица (в важной
// зоне), строим «пандус» свет→тень из НАСТОЯЩИХ пикселей и досаживаем в палитру
// те телесные тона, которых там ещё нет. Тогда кожа квантуется в живую плоть.

function isSkinPixel(r: number, g: number, b: number): boolean {
  if (r < 60 || g < 30 || b < 15) return false;
  if (r < g || g < b) return false;            // кожа: R>=G>=B
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  if (max - min < 8) return false;             // не серое
  if (r - b < 10) return false;                // тёплый сдвиг (тёплые тона кожи)
  const [h, s, l] = rgbToHsl([r, g, b]);
  if (l < 0.18 || l > 0.95) return false;
  if (s < 0.10 || s > 0.80) return false;
  return h <= 55 || h >= 335;                  // красно-оранжевый диапазон кожи
}

/** Досаживает в палитру недостающие телесные тона лица. Возвращает кол-во добавленных. */
function augmentPaletteWithSkin(
  data: Uint8Array, W: number, H: number, numColors: number,
  importanceMap: Float32Array | null,
  paletteArr: [number, number, number][],
  paletteMap: any,
): number {
  if (!importanceMap) return 0; // без карты значимости не отличим лицо от кожецветных предметов
  const N = W * H;
  const stride = N > 400000 ? 2 : 1;
  const skin: { r: number; g: number; b: number; l: number }[] = [];
  for (let y = 0; y < H; y += stride) {
    for (let x = 0; x < W; x += stride) {
      const i = y * W + x;
      const imp = importanceMap[i];
      if (imp < 0.45) continue;                // только субъект (лицо/объект)
      const p = i * 4;
      const r = data[p], g = data[p + 1], b = data[p + 2];
      if (!isSkinPixel(r, g, b)) continue;
      skin.push({ r, g, b, l: 0.299 * r + 0.587 * g + 0.114 * b });
    }
  }
  const sampled = N / (stride * stride);
  if (skin.length < 150 || skin.length < sampled * 0.004) return 0; // не портрет — не трогаем

  // «Пандус»: делим кожу по яркости на K корзин, усредняем РЕАЛЬНЫЕ RGB в каждой.
  skin.sort((a, b) => a.l - b.l);
  const K = Math.max(3, Math.min(6, Math.round(numColors * 0.28)));
  const ramp: [number, number, number][] = [];
  for (let k = 0; k < K; k++) {
    const lo = Math.floor((skin.length * k) / K);
    const hi = Math.floor((skin.length * (k + 1)) / K);
    if (hi <= lo) continue;
    let sr = 0, sg = 0, sb = 0;
    for (let j = lo; j < hi; j++) { sr += skin[j].r; sg += skin[j].g; sb += skin[j].b; }
    const c = hi - lo;
    ramp.push([Math.round(sr / c), Math.round(sg / c), Math.round(sb / c)]);
  }

  // Добавляем лишь те телесные тона, которых в палитре ЕЩЁ НЕТ (dedup по ΔE2000).
  const isMap = paletteMap instanceof Map;
  let maxKey = -1;
  const keys = isMap ? Array.from(paletteMap.keys()) : Object.keys(paletteMap).map(Number);
  for (const k of keys as number[]) if (k > maxKey) maxKey = k;
  const existing: [number, number, number][] = paletteArr.filter(Boolean) as any;
  const existingLab = existing.map((e) => rgbToLab(e));
  let added = 0;
  for (const col of ramp) {
    const lab = rgbToLab(col);
    let dup = false;
    for (const el of existingLab) { if (deltaE00(lab, el) < 6) { dup = true; break; } }
    if (dup) continue;
    maxKey++;
    paletteArr[maxKey] = col;
    if (isMap) paletteMap.set(maxKey, col); else paletteMap[maxKey] = col;
    existingLab.push(lab);
    added++;
  }
  return added;
}

// ─────────────────────────────────────────────────────────────
// УПРОЩЕНИЕ ФОНА НА ПОРТРЕТАХ (борьба с «рассыпанным» пёстрым фоном)
// ─────────────────────────────────────────────────────────────
//
// Пёстрый фон (листва, лес) рассыпается в тысячи мелких зон — некрасиво и
// нераскрашиваемо. Решение: ДО сегментации выборочно размываем НИЗКО-важные
// (фоновые) области, оставляя лицо/объект нетронутыми. Движок затем строит из
// сглаженного фона крупные чистые зоны, а субъект остаётся чётким. Не трогает
// не-портреты (где нет явного разделения субъект/фон).

function boxBlurRGB(src: Uint8Array, W: number, H: number, r: number): Uint8Array {
  const N = W * H;
  const tmp = new Float32Array(N * 3);
  const out = new Uint8Array(N * 4);
  const win = 2 * r + 1;
  // Горизонтальный проход
  for (let y = 0; y < H; y++) {
    let sr = 0, sg = 0, sb = 0;
    for (let x = -r; x <= r; x++) { const xx = x < 0 ? 0 : x >= W ? W - 1 : x; const p = (y * W + xx) * 4; sr += src[p]; sg += src[p + 1]; sb += src[p + 2]; }
    for (let x = 0; x < W; x++) {
      const o = (y * W + x) * 3; tmp[o] = sr / win; tmp[o + 1] = sg / win; tmp[o + 2] = sb / win;
      const xa = x + r + 1 >= W ? W - 1 : x + r + 1, xr = x - r < 0 ? 0 : x - r;
      const pa = (y * W + xa) * 4, pr = (y * W + xr) * 4;
      sr += src[pa] - src[pr]; sg += src[pa + 1] - src[pr + 1]; sb += src[pa + 2] - src[pr + 2];
    }
  }
  // Вертикальный проход
  for (let x = 0; x < W; x++) {
    let sr = 0, sg = 0, sb = 0;
    for (let y = -r; y <= r; y++) { const yy = y < 0 ? 0 : y >= H ? H - 1 : y; const o = (yy * W + x) * 3; sr += tmp[o]; sg += tmp[o + 1]; sb += tmp[o + 2]; }
    for (let y = 0; y < H; y++) {
      const p = (y * W + x) * 4; out[p] = Math.round(sr / win); out[p + 1] = Math.round(sg / win); out[p + 2] = Math.round(sb / win); out[p + 3] = 255;
      const ya = y + r + 1 >= H ? H - 1 : y + r + 1, yr = y - r < 0 ? 0 : y - r;
      const oa = (ya * W + x) * 3, or2 = (yr * W + x) * 3;
      sr += tmp[oa] - tmp[or2]; sg += tmp[oa + 1] - tmp[or2 + 1]; sb += tmp[oa + 2] - tmp[or2 + 2];
    }
  }
  return out;
}

function smoothBackgroundByImportance(data: Uint8Array, W: number, H: number, importanceMap: Float32Array | null, strength: number = 1): Uint8Array {
  if (!importanceMap || strength <= 0) return data; // strength 0 = упрощение фона выключено
  const N = W * H;
  // Ворота: применяем только если есть ЯВНЫЙ субъект И ЯВНЫЙ фон (портрет/объект).
  let bg = 0, fg = 0;
  for (let i = 0; i < N; i++) { const v = importanceMap[i]; if (v >= 1.5) { fg++; continue; } if (v < 0.30) bg++; else if (v > 0.60) fg++; }
  if (bg < N * 0.10 || fg < N * 0.05) return data; // не портрет — не трогаем фон

  // Радиус масштабируется силой: 1 = обычно, 2–3 = сильнее упрощаем фон.
  const radius = Math.max(3, Math.round((Math.max(W, H) / 170) * strength)); // ~5 при 900px и strength=1
  const blurred = boxBlurRGB(data, W, H, radius);
  const out = new Uint8Array(data.length);
  const lo = 0.30, hi = 0.58, inv = 1 / (hi - lo);
  for (let i = 0; i < N; i++) {
    const v = importanceMap[i] >= 1.5 ? 1 : importanceMap[i];
    let t = (v - lo) * inv; t = t < 0 ? 0 : t > 1 ? 1 : t; // t: 1=субъект(оригинал), 0=фон(размытие)
    const s = t * t * (3 - 2 * t); // smoothstep — мягкая граница
    const p = i * 4;
    out[p] = Math.round(data[p] * s + blurred[p] * (1 - s));
    out[p + 1] = Math.round(data[p + 1] * s + blurred[p + 1] * (1 - s));
    out[p + 2] = Math.round(data[p + 2] * s + blurred[p + 2] * (1 - s));
    out[p + 3] = data[p + 3];
  }
  return out;
}

self.onmessage = async function (e: MessageEvent) {
  const { type } = e.data;

      // 1. ГЕНЕРАЦИЯ СХЕМЫ ИЗ ИЗОБРАЖЕНИЯ (WASM)
  if (type === "process") {
    const { imgBuffer, width: W, height: H, numColors, detail, importanceMap: impBuffer, bgSimplify } = e.data.payload;
    const data = new Uint8Array(imgBuffer);
    const importanceMap = impBuffer ? new Float32Array(impBuffer) : null;
    // Упрощение фона: на портретах/объектных фото размываем фон ДО сегментации,
    // чтобы он шёл крупными чистыми зонами (лицо/объект не трогаются). Сила задаётся
    // параметром bgSimplify (ИИ-зрение может её крутить). На не-портретах — без изменений.
    const segData = smoothBackgroundByImportance(data, W, H, importanceMap, typeof bgSimplify === "number" ? bgSimplify : 1);

    const postProgress = (msg: string, pct: number) => {
      self.postMessage({ type: "progress", msg, pct });
    };

    try {
      if (!wasmInited) {
        postProgress("Инициализация ядра...", 2);
        await initWasm();
        await gpuProcessor.init();
        wasmInited = true;
      }

      let res: any;

      if (gpuProcessor.getDevice()) {
        postProgress("Анализ палитры...", 5);
        // We request a 30% buffer (min +2) to absorb JPEG noise and anti-aliasing artifacts
        const internalColors = Math.min(255, Math.floor(numColors * 1.3) + 2);
        const paletteMap: any = extract_palette(segData, W, H, internalColors, importanceMap);
        const paletteArr: [number, number, number][] = [];
        
        if (paletteMap instanceof Map) {
            paletteMap.forEach((val, key) => paletteArr[key] = val);
        } else {
            for (const key of Object.keys(paletteMap)) {
                paletteArr[Number(key)] = paletteMap[key];
            }
        }

        // Кожезависимая палитра: досаживаем недостающие телесные тона лица,
        // чтобы кожа не мапилась в синий/розовый. Портреты определяются автоматически
        // (по карте значимости + цвету кожи); на не-портретах ничего не меняется.
        augmentPaletteWithSkin(segData, W, H, numColors, importanceMap, paletteArr, paletteMap);

        postProgress("Глубокая фильтрация (WebGPU)...", 20);
        const radius = detail >= 9 ? 1 : detail >= 7 ? 2 : detail >= 4 ? 3 : 4;
        const maskU8 = await gpuProcessor.runPixelPipeline(segData, W, H, paletteArr, radius, detail, importanceMap);
        
        if (!maskU8) throw new Error("GPU pipeline returned null");

        postProgress("Векторизация контуров...", 70);
        // We pass the EXACT user requested numColors to the final processor to strictly enforce the limit
        res = process_from_mask(segData, maskU8, W, H, paletteMap, detail, numColors, importanceMap);
      } else {
        postProgress("Векторизация (CPU-резерв)...", 10);
        const internalColors = Math.min(255, Math.floor(numColors * 1.3) + 2);
        res = process_image(segData, W, H, internalColors, detail, numColors, importanceMap || undefined);
      }
      
      postProgress("Финальная сборка...", 95);

      const { data: msgData, transfer } = buildResultMessage(res, W, H, detail);

      postProgress("Готово!", 100);

      (self as any).postMessage({ type: "result", data: msgData }, transfer);
    } catch (error: any) {
      console.error(error);
      self.postMessage({ type: "error", error: error.message });
    }
  }

  // 1b. РЕ-ВЕКТОРИЗАЦИЯ ОТРЕДАКТИРОВАННОЙ МАСКИ (ручной редактор)
  // Берём готовую маску зон + палитру и заново строим контуры/номера/превью
  // БЕЗ фильтрации — правки пользователя сохраняются точно.
  if (type === "revectorize") {
    const { maskBuffer, palette, width: W, height: H, detail } = e.data.payload;
    try {
      if (!wasmInited) {
        await initWasm();
        await gpuProcessor.init();
        wasmInited = true;
      }
      const mask = new Uint8Array(maskBuffer);
      const res: any = vectorize_mask(mask, palette, W, H, detail);
      const { data, transfer } = buildResultMessage(res, W, H, detail);
      (self as any).postMessage({ type: "result", data }, transfer);
    } catch (error: any) {
      console.error(error);
      self.postMessage({ type: "error", error: error.message });
    }
  }

  // 2. ГЕНЕРАЦИЯ SVG В ФОНЕ
  if (type === "export_svg") {
    const {
      res, numberWeight, colored, activeArray, showNums,
      isArtisticMode, artisticStep, artisticPresetId,
      notanLevels = 2,
      notanThreshold = 128,
      artIntensity = 100,
      customArtPalette,
      // Флаги для «архива SVG»: позволяют собрать варианты «только контуры»,
      // «только заливка», «контуры на прозрачном фоне» из одного генератора.
      showContours = true,
      transparentBg,
    } = e.data.payload;

    const { imgW, imgH, contoursData, colorPalette } = res;
    const active = new Set(activeArray);
    const sorted = [...contoursData].sort((a: any, b: any) => b.area - a.area);

    let activePalette: Record<number, [number, number, number]> = {};

    for (const [key, rgb] of Object.entries(colorPalette)) {
      const id = Number(key);
      const rgbArr = rgb as [number, number, number];
      if (isArtisticMode) {
        activePalette[id] = computeArtisticColor(
          rgbArr, artisticStep, artisticPresetId || 'original',
          notanLevels, notanThreshold, artIntensity,
          customArtPalette,
        );
      } else {
        activePalette[id] = rgbArr;
      }
    }

    // #6: в художественном режиме схлопываем визуально совпавшие стилизованные цвета
    if (isArtisticMode) {
      activePalette = canonicalizeStyledPalette(activePalette);
    }

    const fillsArr: string[] = [];
    const shouldFill = isArtisticMode ? artisticStep > 0 && artisticStep < 3 : colored;

    if (shouldFill) {
      for (const cd of sorted) {
        const smoothed = cd.points;
        if (smoothed && smoothed.length > 0) {
          const act = isArtisticMode || active.has(cd.labelId);
          const col = activePalette[cd.labelId];
          
          let d = `M ${smoothed[0][0].toFixed(1)} ${smoothed[0][1].toFixed(1)} `;
          for (let i = 1; i < smoothed.length; i++) {
             d += `L ${smoothed[i][0].toFixed(1)} ${smoothed[i][1].toFixed(1)} `;
          }
          d += "Z";

          fillsArr.push(act && col
            ? `<path d="${d}" fill="rgb(${col[0]},${col[1]},${col[2]})"/>`
            : `<path d="${d}" fill="white"/>`);
        }
      }
    }
    const fills = fillsArr.join("");

    let lines = "";
    const shouldDrawLines = (isArtisticMode ? artisticStep === 0 || artisticStep === 3 : true) && showContours;

    if (shouldDrawLines) {
      const chains = res.chains;

      // Уплотняем длинные сегменты, чтобы контрольные точки безье оставались
      // локальными и кривая не "орбитила". Раньше длинные прямые границы
      // целиком выкидывались (return "") и пропадали из SVG.
      const densify = (src: [number, number][], maxLen = 60): [number, number][] => {
        if (src.length < 2) return src;
        const out: [number, number][] = [src[0]];
        for (let i = 1; i < src.length; i++) {
          const [x0, y0] = src[i - 1];
          const [x1, y1] = src[i];
          const dist = Math.hypot(x1 - x0, y1 - y0);
          const steps = Math.max(1, Math.ceil(dist / maxLen));
          for (let s = 1; s <= steps; s++) {
            out.push([x0 + (x1 - x0) * (s / steps), y0 + (y1 - y0) * (s / steps)]);
          }
        }
        return out;
      };

      const getBezierPath = (rawPts: [number, number][]) => {
        if (rawPts.length < 2) return "";
        const pts = densify(rawPts, 60);
        let d = `M ${pts[0][0].toFixed(1)} ${pts[0][1].toFixed(1)}`;
        if (pts.length === 2) {
          d += ` L ${pts[1][0].toFixed(1)} ${pts[1][1].toFixed(1)}`;
          return d;
        }
        const n = pts.length;
        const t = 0.15;
        for (let i = 0; i < n - 1; i++) {
          const p0 = pts[i === 0 ? 0 : i - 1];
          const p1 = pts[i];
          const p2 = pts[i + 1];
          const p3 = pts[i + 2 >= n ? n - 1 : i + 2];
          const cp1x = p1[0] + (p2[0] - p0[0]) * t;
          const cp1y = p1[1] + (p2[1] - p0[1]) * t;
          const cp2x = p2[0] - (p3[0] - p1[0]) * t;
          const cp2y = p2[1] - (p3[1] - p1[1]) * t;
          d += ` C ${cp1x.toFixed(1)} ${cp1y.toFixed(1)}, ${cp2x.toFixed(1)} ${cp2y.toFixed(1)}, ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;
        }
        return d;
      };

      const strokeColor = isArtisticMode ? "rgba(40,40,40,0.6)" : "rgba(40,40,40,0.4)";
      const svgPaths = chains.map((ch: [number, number][]) => {
        const d = getBezierPath(ch);
        if (!d) return "";
        return `<path d="${d}" fill="none" stroke="${strokeColor}" stroke-width="1.0" stroke-linecap="round" stroke-linejoin="round"/>`;
      }).join("");
      lines = svgPaths;
    }

    const textsArr: string[] = [];
    if (showNums && !isArtisticMode) {
      const numAlpha = (0.15 + (numberWeight / 100) * 0.85).toFixed(2);
      for (const cd of sorted) {
        for (const lbl of cd.labelPositions) {
          if (lbl.maxDist < 2.5) continue;
          const digits = String(cd.labelId + 1).length;
          const fitFs = (3.27 * lbl.maxDist) / digits;
          const fs = Math.max(5, Math.min(12, lbl.maxDist * 1.2, fitFs));
          const act = colored && active.has(cd.labelId);
          const col = colorPalette[cd.labelId];
          let tf = `rgba(51,51,51,${numAlpha})`;

          if (act && col) {
            const lum = 0.299 * col[0] + 0.587 * col[1] + 0.114 * col[2];
            tf = lum > 140 ? `rgba(0,0,0,${numAlpha})` : `rgba(255,255,255,${numAlpha})`;
          }

          const labelText = escapeXml(String(cd.labelId + 1));
          textsArr.push(`<text x="${lbl.x.toFixed(1)}" y="${lbl.y.toFixed(1)}" font-size="${fs.toFixed(1)}" text-anchor="middle" dominant-baseline="central" font-family="sans-serif" font-weight="bold" fill="${tf}">${labelText}</text>`);
        }
      }
    }
    const texts = textsArr.join("");

    const svgString = generateSvgTemplate({
      imgW, imgH,
      isTransparent: transparentBg ?? (isArtisticMode && artisticStep === 3),
      fills, lines, texts
    });

    self.postMessage({ type: "export_result", data: svgString });
  }

  // 3. ГЕНЕРАЦИЯ HTML В ФОНЕ
  if (type === "export_html") {
    const {
      res, contourWeight, isArtisticMode, origBase64,
      artisticPresetId, notanLevels = 2, notanThreshold = 128,
      artIntensity = 100, customArtPalette,
    } = e.data.payload;

    const { imgW, imgH, colorPalette, validLabels, contoursData, labelMask } = res;
    const sl = [...validLabels].sort((a: number, b: number) => a - b);
    const palJSON: Record<number, [number, number, number]> = {};
    for (const lid of sl) {
      const c = colorPalette[lid];
      if (c) palJSON[lid] = c;
    }

    const maskRLE = rleEncode(labelMask);

    const chains = res.chains;
    const chainsJSON = JSON.stringify(
      chains.map((ch: any) => ch.map(([x, y]: any) => [Math.round(x * 10) / 10, Math.round(y * 10) / 10]))
    );

    const labelsJSON = JSON.stringify(
      contoursData.map((cd: any) => ({
        id: cd.labelId,
        a: cd.area,
        poly: cd.points.map(([x, y]: any) => [Math.round(x * 10) / 10, Math.round(y * 10) / 10]),
        lp: cd.labelPositions
          .filter((lp: any) => lp.maxDist >= 2.5) // тот же порог, что в редакторе — набор номеров совпадает
          .map((lp: any) => ({
            x: Math.round(lp.x * 10) / 10,
            y: Math.round(lp.y * 10) / 10,
            d: Math.round(lp.maxDist * 10) / 10,
          })),
      }))
    );

    const lineAlpha = String(contourWeight === 0 ? "0" : (0.2 + (contourWeight / 100) * 0.8).toFixed(2));
    const lineWidth = String(contourWeight === 0 ? "0" : (0.5 + (contourWeight / 100) * 1.5).toFixed(2));

    let htmlString = "";
    if (isArtisticMode) {
      const customPalJS = customArtPalette && customArtPalette.length >= 2 ? JSON.stringify(customArtPalette) : 'null';
      htmlString = generateArtisticHtmlTemplate({
        imgW, imgH, palJSON, chainsJSON, maskRLE,
        notanLevels, notanThreshold, artIntensity,
        artisticPresetId: artisticPresetId || 'original',
        customPalJS, origBase64
      });
    } else {
      const palButtons = sl.map((lid: number) => {
        const c = colorPalette[lid]; if (!c) return "";
        const lum = 0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2];
        const tc = lum > 140 ? "#000" : "#fff";
        return `<div id="p${lid}" class="cb" onclick="tc(${lid})" style="background:rgb(${c[0]},${c[1]},${c[2]});color:${tc}" title="Цвет ${lid + 1}"><span>${lid + 1}</span></div>`;
      }).join("");

      htmlString = generatePbnHtmlTemplate({
        imgW, imgH, palJSON, chainsJSON, labelsJSON, maskRLE, sl, lineAlpha, lineWidth, palButtons
      });
    }

    self.postMessage({ type: "export_result", data: htmlString });
  }
};