// src/generator/utils/worker/labels.ts

export function resolveAllLabelCollisions(contours: any[], w: number, h: number, mask: Uint8Array): void {
  // Собираем все метки в один плоский список для обработки
  const allLabels: any[] = [];
  for (const cd of contours) {
    for (const lbl of cd.labelPositions) {
      if (lbl.maxDist < 1.0) continue;
      allLabels.push({
        lbl,
        id: cd.labelId,
        area: cd.area
      });
    }
  }

  // Сортируем: сначала метки для маленьких зон (они важнее, так как их сложнее разместить)
  allLabels.sort((a, b) => a.area - b.area);

  // Оптимизация O(N^2) -> O(N) через Spatial Hashing Grid
  // Разбиваем холст на ячейки (например, 32x32 пикселя), чтобы проверять коллизии только с ближайшими соседями
  const CELL_SIZE = 32;
  const gridCols = Math.ceil(w / CELL_SIZE);
  const gridRows = Math.ceil(h / CELL_SIZE);
  const grid: { x: number; y: number; r: number; id: number }[][] = new Array(gridCols * gridRows).fill(null).map(() => []);

  const getCellIndex = (x: number, y: number) => {
    const col = Math.max(0, Math.min(gridCols - 1, Math.floor(x / CELL_SIZE)));
    const row = Math.max(0, Math.min(gridRows - 1, Math.floor(y / CELL_SIZE)));
    return row * gridCols + col;
  };

  const getNeighbors = (cx: number, cy: number) => {
    const col = Math.floor(cx / CELL_SIZE);
    const row = Math.floor(cy / CELL_SIZE);
    const neighbors: { x: number; y: number; r: number; id: number }[] = [];
    
    for (let r = Math.max(0, row - 1); r <= Math.min(gridRows - 1, row + 1); r++) {
      for (let c = Math.max(0, col - 1); c <= Math.min(gridCols - 1, col + 1); c++) {
        const idx = r * gridCols + c;
        const cell = grid[idx];
        for (let i = 0; i < cell.length; i++) {
          neighbors.push(cell[i]);
        }
      }
    }
    return neighbors;
  };

  for (const item of allLabels) {
    const { lbl } = item;
    const fs = Math.max(6, Math.min(14, lbl.maxDist * 1.2));
    const textR = fs * 0.7; 

    let cx = lbl.x, cy = lbl.y;

    for (let att = 0; att < 10; att++) {
      let collided = false;
      let nextCx = cx;
      let nextCy = cy;

      const candidates = getNeighbors(nextCx, nextCy);

      for (let i = 0; i < candidates.length; i++) {
        const p = candidates[i];
        const dx = nextCx - p.x;
        const dy = nextCy - p.y;
        const minDist = textR + p.r + 2; 
        
        if (dx * dx + dy * dy < minDist * minDist) {
          const dist = Math.sqrt(dx * dx + dy * dy) || 1;
          const force = (minDist - dist) / dist;
          
          nextCx += dx * force * 0.6;
          nextCy += dy * force * 0.6;
          collided = true;
        }
      }

      if (collided) {
        const ix = Math.floor(nextCx);
        const iy = Math.floor(nextCy);
        if (ix >= 0 && ix < w && iy >= 0 && iy < h && mask[iy * w + ix] === item.id) {
          cx = nextCx;
          cy = nextCy;
        } else {
          break;
        }
      } else {
        break;
      }
    }

    lbl.x = cx;
    lbl.y = cy;
    const placedObj = { x: cx, y: cy, r: textR, id: item.id };
    grid[getCellIndex(cx, cy)].push(placedObj);
  }
}
